interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  errorMessage: string;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, errorMessage: '' };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, errorMessage: error.message };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log error to telemetry service
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-fallback-card">
          <h3>Something went wrong</h3>
          <p>{this.state.errorMessage}</p>
        </div>
      );
    }
    return this.props.children;
  }
}`}]}]},{id:"nextjs",num:"06",name:"Next.js",category:"Frontend",badge:"Full-Stack Framework",version:"Next.js 15 (App Router)",accentColor:"#ffffff",tagline:"The React Framework for high-performance production web applications",overview:"Next.js is the full-stack React framework featuring the App Router, React Server Components (RSC), Server Actions, nested layouts, static site generation (SSG), incremental static regeneration (ISR), and automatic image/font optimization.",keyHighlights:["App Router architecture with directory-based file conventions (page.tsx, layout.tsx)","React Server Components for zero-bundle-size server rendering","Server Actions for seamless form submissions without writing API routes"],coreConcepts:[{title:"Server Components vs Client",desc:'Server Components fetch data directly with zero client JS; "use client" handles browser interactivity.'},{title:"Route Handlers",desc:"Writing custom GET/POST HTTP endpoints directly in app/api/route.ts."},{title:"Server Actions",desc:"Async functions executed on the server called directly from forms or buttons."},{title:"Caching & ISR",desc:"Four-tier caching architecture (Data Cache, Request Memoization, Full Route Cache, Router Cache)."}],methodsAndCommands:[{name:"npx create-next-app",signature:"npx create-next-app@latest",returns:"CLI",desc:"Bootstraps a new production Next.js application."},{name:"revalidatePath()",signature:'(path: string, type?: "page"|"layout") => void',returns:"void",desc:"Purges cached data on-demand for a specific path."},{name:"redirect()",signature:"(url: string, type?: RedirectType) => never",returns:"never",desc:"Redirects the user to another route from a Server Component or Server Action."},{name:"cookies()",signature:"() => ReadonlyRequestCookies",returns:"Cookies",desc:"Reads incoming HTTP request cookies in a Server Component."}],codeExamples:[{title:"Server Component with Server Action in Next.js 15",code:`// app/posts/page.tsx
import { revalidatePath } from 'next/cache';

